function lessonHTML(p,v,controls=true){
 let actions='';if(controls){if(p.status==='active'){const rem=p.minutes-p.progress, available=Math.min(rem,v.budget);const times=[...new Set([30,60,120,240,available])].filter(n=>n>0&&n<=available);actions=times.map(n=>button('+'+timeLabel(n),'study',{id:p.id,minutes:n})).join('')+button('Pause','pauseLesson',{id:p.id});}if(p.status==='paused')actions=button('Resume','resumeLesson',{id:p.id});if(liveLesson(p))actions+=button('Cancel (no refund)','cancelLesson',{id:p.id});}
 return `<div class="art-entry"><b>${esc(p.name)}</b> · ${esc(p.status)}<p class="art-muted">${esc(p.sourceName)} · ${esc(p.kind==='npc'?'NPC Training':'Book Study')}</p><progress value="${p.progress}" max="${p.minutes}"></progress>${timeLabel(p.progress)} / ${timeLabel(p.minutes)}<div class="art-actions">${actions}</div></div>`;
}
function lessonOfferHTML(source,kind,busy){
 return panel(source.name,source.recipes.map(r=>`<div class="art-entry">${row(r.name,esc(r.rarity))}<small>${esc(r.tools)} · ${timeLabel(r.minutes)} · ${r.gp} GP</small><div class="art-actions">${r.eligible&&!busy?button(kind==='npc'?'Request Training':'Study Recipe','startLesson',{kind,source:source.id,id:r.id,gp:r.gp,minutes:r.minutes}):`<span class="art-muted">${!r.eligible?'Missing proficiency':'Pause your active project first'}</span>`}</div></div>`).join('')||'<p class="art-muted">All recipes in this book are learned.</p>');
}
function bookData(name,ids){const rs=ids.map(lookup);return {name,type:'loot',img:'icons/svg/book.svg',system:{quantity:1,description:{value:`<p>Study this reusable recipe book through Artisan → Learning.</p><ul>${rs.map(r=>`<li>${esc(r.name)} — ${timeLabel(BOOK_MINUTES[r.rarity])}</li>`).join('')}</ul>`}},flags:{[F]:{recipeBook:ids}}};}
function learningDialog(title,{name='',recipes=[],selected=[],customers=[],selectedCustomers=[],rates=null}){
 return new Promise(resolve=>{
 const selectedSet=new Set(selected),customerSet=new Set(selectedCustomers);
 const rows=recipes.map(r=>`<label class="art-recipe-choice" data-search="${esc((r.name+' '+r.category+' '+r.rarity).toLowerCase())}" style="display:block;margin:3px 0"><input type="checkbox" name="recipeId" value="${esc(r.id)}" ${selectedSet.has(r.id)?'checked':''}> ${esc(r.name)} <small>(${esc(r.rarity)})</small></label>`).join('');
 const content=`${rates?'':`<label>Book name <input name="bookName" value="${esc(name)}"></label>`}${rates?`<h4>Allowed students</h4><div style="max-height:115px;overflow:auto">${customers.map(([id,n])=>`<label style="display:block"><input type="checkbox" name="customerId" value="${esc(id)}" ${customerSet.has(id)?'checked':''}> ${esc(n)}</label>`).join('')||'No player characters'}</div><h4>Training rates (GP / minutes)</h4>${Object.entries(rates).map(([rarity,q],i)=>`<div class="form-group"><label>${esc(rarity)}</label><input name="gp${i}" type="number" min="0" value="${q.gp}"><input name="minutes${i}" type="number" min="1" value="${q.minutes}"></div>`).join('')}`:''}<h4>${rates?'Teachable recipes (already learned by NPC)':'Recipes in the book'}</h4><input name="learnSearch" placeholder="Filter recipes"><div style="max-height:230px;overflow:auto">${rows||'No recipes available'}</div>`;
 new foundry.appv1.api.Dialog({title,content,render:h=>{h.find('[name=learnSearch]').on('input',e=>{const q=e.currentTarget.value.toLowerCase();h.find('.art-recipe-choice').each((_,el)=>{el.style.display=el.dataset.search.includes(q)?'block':'none';});});},buttons:{ok:{label:'Save',callback:h=>{const vals=n=>h.find('[name='+n+']:checked').map((_,x)=>x.value).get();const out={name:h.find('[name=bookName]').val(),recipes:vals('recipeId'),customers:vals('customerId')};if(rates)out.rates=Object.fromEntries(Object.keys(rates).map((k,i)=>[k,{gp:Number(h.find('[name=gp'+i+']').val()),minutes:Number(h.find('[name=minutes'+i+']').val())}]));resolve(out);}},cancel:{label:'Cancel',callback:()=>resolve(null)}},close:()=>resolve(null)},{width:620}).render(true);
 });
}
function checkStart(a,as,r,target,ignoreActive=false){if(!as.learned.includes(r.id))throw Error('Recipe not learned');checkTools(a,r);if(!as.workshops.includes(workshop(r)))throw Error('Workshop unavailable: '+workshop(r));if(!ignoreActive&&(busyCraft(as)||activeLesson(as)))throw Error('Active project occupied');for(const m of r.materials)if(have(a,m.id)<m.qty)throw Error('Missing '+m.name);if(money(a)<r.gp*100)throw Error('Insufficient funds');if(['Enchanting','Runecrafting'].includes(r.category)){const i=a.items.get(target),slot=r.category==='Enchanting'?'enchantment':'rune';if(!targetOkay(i,r)||i.getFlag(F,slot)||i.getFlag(F,'reserved'))throw Error('Invalid or occupied target');if(quantity(i)!==1)throw Error('Target must be a single item');}else if(r.category!=='Cooking'&&!state.links.results[r.id])throw Error('GM must link a result Item before crafting');}
async function begin(a,as,r,target){if(!['Enchanting','Runecrafting'].includes(r.category))target=null;checkStart(a,as,r,target);if(!target&&r.category!=='Cooking'){const i=await fromUuid(state.links.results[r.id]);if(i?.documentName!=='Item')throw Error('Result link is invalid');}const escrow=await take(a,r.materials);try{await pay(a,r.gp);if(target)await a.items.get(target).setFlag(F,'reserved',true);}catch(e){await restore(a,escrow);throw e;}as.projects.push({id:uid(),recipe:clone(r),target:target||null,escrow,progress:0,status:'active'});note(as,'Started '+r.name);}
async function complete(a,as,p,chosen=[]){const r=p.recipe,o=p.outcome,lost=lossPlan(r.materials,o.loss,chosen);if(o.success||r.category==='Cooking'&&o.quantity){if(['Enchanting','Runecrafting'].includes(r.category)){const item=a.items.get(p.target);if(!item)throw Error('Target missing; GM must resolve');const slot=r.category==='Enchanting'?'enchantment':'rune';if(item.getFlag(F,slot))throw Error('Slot already filled');await item.setFlag(F,slot,{id:r.id,name:r.name,effect:r.effect,attunement:r.attunement,active:false});await item.update({'system.description.value':(item.system.description?.value||'')+`<hr><p><strong>${esc(r.name)}</strong> (${esc(slot)}): ${esc(r.effect)}</p>`});}else{let data;if(r.category==='Cooking'){data=mealData(r,o.quantity,o.benefit);}else{const item=await fromUuid(state.links.results[r.id]);if(!item)throw Error('Result Item link missing');data=item.toObject();delete data._id;data.system.quantity=o.quantity;data.flags??={};data.flags[F]={...(data.flags[F]||{}),recipe:r.id,masterwork:!!o.masterwork};}await a.createEmbeddedDocuments('Item',[data]);}if(r.experimental&&!as.learned.includes(r.id))as.learned.push(r.id);}
 await restore(a,p.escrow,lost);if(p.target&&a.items.get(p.target))await a.items.get(p.target).unsetFlag(F,'reserved');p.escrow=[];p.status=o.success?'completed':o.quantity?'partial':'failed';note(as,`${r.name}: ${p.status}`);await chat(a,`${r.name}: ${p.status}${o.quantity?` (${o.quantity})`:''}`);}
async function chat(a,t){await ChatMessage.create({speaker:ChatMessage.getSpeaker({actor:a}),content:`<div class="averis-chat"><b>Artisan</b> — ${esc(t)}</div>`});}
async function roll(formula){const r=await new Roll(formula).evaluate();return {total:r.total,nat:r.dice[0]?.results.find(x=>x.active)?.result};}
async function persist(){await db.setFlag(F,'state',state);}
function publicRecipe(r){const {dc,...v}=r;return {...v,description:r.description.replace(/(?:Known Recipe |Cooking )?DC\s*:?\s*\d+/gi,'DC: hidden'),linked:!!state.links.results[r.id],workshop:workshop(r)};}
function view(a){const as=actorState(state,a),region=state.regions[as.region];return {cooking:mealView(a,as),learning:learningView(a,as),budget:as.budget,workshops:as.workshops,region:region?.name||'',recipes:state.catalog.recipes.filter(r=>as.learned.includes(r.id)).map(publicRecipe),projects:as.projects.map(p=>({id:p.id,name:p.recipe.name,minutes:p.recipe.minutes,progress:p.progress,status:p.status})),history:as.history,requests:state.requests.filter(q=>q.actor===a.id).map(q=>({name:q.name,status:q.status})),resources:ordered((region?.patches||[]).filter(p=>!p.hidden).map(p=>gatherView(resource(p.resource),p,state.day))),materials:ordered(state.catalog.materials.filter(m=>have(a,m.id)>0).map(m=>({id:m.id,name:m.name,rarity:m.rarity,qty:have(a,m.id)}))),services:Object.entries(state.actors).filter(([id,n])=>n.npc&&n.npc.enabled&&n.npc.customers.includes(a.id)).map(([id,n])=>({id,name:game.actors.get(id)?.name,recipes:state.catalog.recipes.filter(r=>n.learned.includes(r.id)&&!['Runecrafting','Enchanting','Cooking'].includes(r.category)).map(r=>({id:r.id,name:r.name,gp:r.gp,minutes:r.minutes})),fee:n.npc.fee})),orders:state.orders.filter(o=>o.customer===a.id).map(o=>({id:o.id,name:o.recipe.name,status:o.status,progress:o.progress,minutes:o.recipe.minutes})),day:state.day};}
async function publish(a){if(!a)return;const v=view(a);if(JSON.stringify(a.getFlag(F,'view'))!==JSON.stringify(v))await a.setFlag(F,'view',v);}
async function saveAll(){await expireMeals();await persist();for(const id of Object.keys(state.actors))await publish(game.actors.get(id));refresh();}
async function request(a,op,data={}){if(game.user.isGM&&primary())return serialize(async()=>{await action(a,op,data);await saveAll();});if(!game.users.some(u=>u.active&&u.isGM))throw Error('An active GM is required');await a.setFlag(F,'request',{nonce:uid(),op,data});ui.notifications.info('Artisan request sent');}
function addRequest(a,kind,name,data){state.requests.push({id:uid(),actor:a.id,kind,name,data,status:'pending'});}
async function gather(a,as,patchId,stage,methodId,approved=false,regionId=null){
 if(regionId&&regionId!==as.region)throw Error('Region changed; request again');
 const reg=state.regions[as.region],p=reg?.patches.find(x=>x.id===patchId);if(!p)throw Error('Resource unavailable');const r=resource(p.resource);
 refreshPatch(p,r,state.day);
 if(!patchReady(p,state.day))throw Error('Resource unavailable');
 if(r.category==='Mining'&&p.oreUnits===0)throw Error('Deposit has no ore left');
 if(!['search','harvest'].includes(stage)||r.category==='Mining'&&stage!=='harvest')throw Error('Invalid gathering action');
 const found=r.category==='Mining'||p.found;
 if(stage==='search'&&(found||p.searchBlocked||p.failedDay!=null))throw Error('Search already resolved; GM must reset conditions');
 if(stage==='harvest'&&!found)throw Error('Search first');
 const method=gatherMethods(r,stage,p).find(x=>x.id===methodId);if(!method)throw Error('Select an allowed check method');
 const min=gatherDuration(r,p,stage);if(as.budget<min)throw Error('Not enough downtime');
 if(!approved&&approval(r,state.approval)){if(state.requests.some(q=>q.actor===a.id&&q.kind==='gather'&&q.status==='pending'&&q.data.patchId===patchId))throw Error('Request already pending');addRequest(a,'gather',r.name,{patchId,stage,method:method.id,region:as.region});return;}
 const b=gatherBonus(a,method),formula=(p.advantageNext?'2d20kh':'1d20')+(b>=0?'+':'')+b;
 const result=await roll(formula),dc=stage==='search'?r.searchDC:r.harvestDC,ok=result.total>=dc;
 let n=0;if(stage==='harvest'&&ok){const y=r.category==='Mining'?1:(await roll(r.category==='Creatures'&&p.largeSpecimen&&r.rarity!=='Very Rare'?'1d2':r.yieldFormula)).total;n=gatherYield(r,p,result.total,dc,y);if(r.category==='Mining'&&p.oreUnits!=null)n=Math.min(n,p.oreUnits);if(n>0)await grantMaterial(a,r.id,n);}
 as.budget-=min;p.advantageNext=false;
 if(stage==='search'){if(ok){p.found=true;p.searchBlocked=false;p.failedDay=null;}else{p.searchBlocked=true;p.failedDay=state.day;}note(as,ok?'Located '+r.name:'Search failed: '+r.name);}
 else{if(r.category==='Mining'&&p.oreUnits!=null)p.oreUnits-=n;consumePatch(p,r,state.day);if(r.category==='Mining'&&p.oreUnits===0){p.remaining=0;p.regrowAt=null;}note(as,ok?`Gathered ${n} × ${r.name}`:'Harvest failed: '+r.name);}
 const hazard=stage==='harvest'&&!ok&&result.total<=dc-5?gatherText(r,'Failure / hazard','Current crafting use')||'GM adjudication':null;
 state.gatherLog??=[];state.gatherLog.unshift({actor:a.name,region:reg.name,resource:r.name,stage,method:method.label,roll:result.total,dc,success:ok,quantity:n,day:state.day,hazard});state.gatherLog=state.gatherLog.slice(0,200);
 if(hazard)await ChatMessage.create({content:`<b>Artisan — Harvest complication</b><p>${esc(a.name)}: ${esc(r.name)} — ${esc(hazard)}</p><p>DM adjudicates.</p>`,whisper:game.users.filter(u=>u.isGM).map(u=>u.id)});
 await chat(a,stage==='search'?(ok?'Located '+r.name:'Search failed: '+r.name):(ok?`Gathered ${n} × ${r.name}`:'Harvest failed: '+r.name));
}
async function action(a,op,d){const as=actorState(state,a);switch(op){case 'refresh':break;case 'start':{const r=lookup(d.id);checkStart(a,as,r,d.target);if(approval(r,state.approval)){if(state.requests.some(q=>q.actor===a.id&&q.kind==='craft'&&q.status==='pending'))throw Error('A crafting request is already pending');addRequest(a,'craft',r.name,{id:r.id,target:d.target});}else await begin(a,as,r,d.target);break;}case 'work':{const p=as.projects.find(x=>x.id===d.id);if(!p)throw Error('Unknown project');as.budget=advance(p,Number(d.minutes),as.budget);break;}case 'pause':case 'resume':{const p=as.projects.find(x=>x.id===d.id);if(!p)throw Error('Unknown project');if(op==='pause'&&p.status==='active')p.status='paused';else if(op==='resume'&&p.status==='paused'&&!busyCraft(as)&&!activeLesson(as))p.status='active';else throw Error('Cannot change project status');break;}case 'cancel':{const p=as.projects.find(x=>x.id===d.id);if(!p||!['active','paused','ready'].includes(p.status))throw Error('Cannot cancel');await restore(a,p.escrow);if(p.target&&a.items.get(p.target))await a.items.get(p.target).unsetFlag(F,'reserved');p.escrow=[];p.status='cancelled';note(as,'Cancelled '+p.recipe.name);break;}case 'finish':{const p=as.projects.find(x=>x.id===d.id);if(!p||p.status!=='ready')throw Error('Project not ready');checkTools(a,p.recipe);if(!as.workshops.includes(workshop(p.recipe)))throw Error('Workshop unavailable');const r=p.recipe,b=mod(a,ability(r),true),rr=await roll('1d20'+(b>=0?'+':'')+b);p.outcome=outcome(r,rr.total,rr.nat);p.roll=rr;p.status='loss';if(typeof p.outcome.loss==='number'){addRequest(a,'loss',r.name,{project:p.id});}else await complete(a,as,p);break;}case 'gather':await gather(a,as,d.id,d.stage,d.method);break;case 'eat':await eatMeal(a,as,d.id);break;case 'shareMeal':await distributeMeal(a,as,d.id,d.shares);break;case 'mealBonus':await spendMealBonus(a,as);break;case 'mealRest':await applyMealRest(a,as,d.longRest===true,Number(d.spent));break;case 'learn':{const i=a.items.get(d.id),rid=i?.getFlag(F,'recipeScroll');if(!rid||quantity(i)<1)throw Error('Not a recipe scroll');const r=lookup(rid);checkTools(a,r);if(as.learned.includes(rid))throw Error('Already learned');if(lessons(as).some(p=>liveLesson(p)&&p.recipe===rid))throw Error('Cancel existing lesson before using this scroll');if(quantity(i)>1)await i.update({'system.quantity':quantity(i)-1});else await i.delete();as.learned.push(rid);note(as,'Learned '+r.name+' from scroll');break;}
 case 'startLesson':{const r=lookup(d.id),q=checkLessonStart(a,as,r,d.kind,d.source);if(q.gp!==d.gp||q.minutes!==d.minutes)throw Error('Lesson offer changed. Refresh and try again.');if(approval(r,state.approval)){if(state.requests.some(x=>x.actor===a.id&&x.kind==='learning'&&x.status==='pending'))throw Error('Learning request already pending');addRequest(a,'learning',r.name,{id:r.id,kind:d.kind,source:d.source,quote:{gp:q.gp,minutes:q.minutes}});}else await beginLesson(a,as,r,d.kind,d.source);break;}
 case 'study':case 'pauseLesson':case 'resumeLesson':case 'cancelLesson':{const p=lessons(as).find(p=>p.id===d.id);if(!p||!liveLesson(p))throw Error('No ongoing lesson');if(op==='study')lessonWork(a,as,p,Number(d.minutes));else if(op==='pauseLesson'&&p.status==='active')p.status='paused';else if(op==='resumeLesson'&&p.status==='paused'&&!busyCraft(as)&&!activeLesson(as)){const r=lookup(p.recipe);if(as.learned.includes(r.id))throw Error('Recipe already learned');checkTools(a,r);learningSource(a,as,p.kind,p.source,r);p.status='active';}else if(op==='cancelLesson'){p.status='cancelled';note(as,'Cancelled learning '+p.name);}else throw Error('Cannot change lesson status');break;}case 'order':{const n=state.actors[d.npc],npc=game.actors.get(d.npc),r=lookup(d.id);if(!n?.npc?.enabled||!n.npc.customers.includes(a.id)||!n.learned.includes(r.id))throw Error('NPC service unavailable');if(['Enchanting','Runecrafting','Cooking'].includes(r.category))throw Error('Only equipment and alchemy NPC orders in preview');if(r.category!=='Cooking'&&!state.links.results[r.id])throw Error('Result Item not linked');if(state.orders.filter(o=>o.npc===npc.id&&!['collected','failed','rejected'].includes(o.status)).length>=n.npc.capacity)throw Error('Order queue full');addRequest(a,'order',r.name,{npc:npc.id,id:r.id});break;}case 'collect':{const o=state.orders.find(o=>o.id===d.id&&o.customer===a.id);if(o?.status!=='ready')throw Error('Order not ready');const item=await fromUuid(state.links.results[o.recipe.id]);if(!item)throw Error('Missing result link');const data=item.toObject();delete data._id;data.system.quantity=o.recipe.quantity;await a.createEmbeddedDocuments('Item',[data]);o.status='collected';note(as,'Collected '+o.recipe.name);break;}default:throw Error('Invalid operation');}}
async function init(){if(!primary())return;db=game.journal.find(j=>j.getFlag(F,'database')===true);if(!db){const catalog=await (await fetch(`modules/${ID}/data/catalog.json`)).json();db=await JournalEntry.create({name:'Averis Artisan — GM Database (do not delete)',ownership:{default:0},flags:{[F]:{database:true}}});state={catalog,actors:{},regions:{},requests:[],orders:[],links:{results:{},materialTemplates:{},materials:{}},day:1,approval:'smart'};await persist();}else state=db.getFlag(F,'state');if(!state)throw Error('Database exists without state; inspect backup before resetting');for(const a of game.actors.filter(a=>['character','npc'].includes(a.type)))actorState(state,a);await saveAll();}
const button=(label,op,data={})=>`<button type="button" data-op="${esc(op)}" data-payload="${esc(JSON.stringify(data))}">${esc(label)}</button>`;
const panel=(title,content)=>`<section class="art-panel"><h3>${esc(title)}</h3>${content}</section>`;
const row=(l,r)=>`<div class="art-row"><span>${esc(l)}</span><span>${r}</span></div>`;
const select=(name,values,selected='')=>`<select name="${esc(name)}">${values.map(([v,l])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
const empty='<p class="art-muted">No entries.</p>';
function actorBy(id){const a=game.actors.get(id);if(!a)throw Error('Actor not found');return a;}
function playerProjectActors(){const players=Array.from(game.users).filter(u=>!u.isGM);return game.actors.filter(a=>a.type==='character'&&players.some(u=>u.character?.id===a.id||a.testUserPermission(u,'OWNER'))).sort((a,b)=>a.name.localeCompare(b.name));}
function playerProjectStates(){return playerProjectActors().map(a=>[a,state.actors[a.id]||{projects:[]}]);}
function actorOptions(){return game.actors.filter(a=>['character','npc'].includes(a.type)).map(a=>[a.id,a.name]);}
function projectHTML(p,v){let s=`<div class="art-entry"><b>${esc(p.name)}</b> <span class="art-muted">${esc(p.status)}</span><progress value="${p.progress}" max="${p.minutes}"></progress>${timeLabel(p.progress)} / ${timeLabel(p.minutes)}<div class="art-actions">`;if(p.status==='active')s+=[30,60,120,240].filter(n=>n<=v.budget&&n<=p.minutes-p.progress).map(n=>button(`+${timeLabel(n)}`,'work',{id:p.id,minutes:n})).join('')+button('Custom work','customWork',{id:p.id})+button('Pause','pause',{id:p.id});if(p.status==='paused')s+=button('Resume','resume',{id:p.id});if(p.status==='ready')s+=button('Crafting Check','finish',{id:p.id});if(['active','paused','ready'].includes(p.status))s+=button('Cancel','cancel',{id:p.id});return s+'</div></div>';}
class ArtisanWindow extends foundry.applications.api.ApplicationV2 {
 static DEFAULT_OPTIONS={id:"averis-artisan-{id}",classes:["averis-artisan"],position:{width:1050,height:700},window:{title:"Averis — Artisan System",resizable:true,minimizable:true}};
 constructor(a=null){super();this.actor=a;this.tab=a?'Overview':'Dashboard';this.filter='';this.category='All';this.rarityFilter='All';this.chosen='';this.gmActor=a?.id||'';wins.add(this);}
 get title(){return this.actor?`Artisan — ${this.actor.name}`:'Artisan — GM Dashboard';}
 async close(options){try{return await super.close(options);}finally{wins.delete(this);if(windowByKey.get(this.windowKey)===this)windowByKey.delete(this.windowKey);}}
 async _renderHTML(_context,_options){const el=document.createElement("div");el.className="artisan-root";el.innerHTML=this.actor?this.player():this.gm();return el;}
 _replaceHTML(result,content,_options){content.replaceChildren(result);this.activateListeners(result);}
 nav(tabs){return `<nav class="art-nav">${tabs.map(t=>`<button type="button" data-tab="${esc(t)}" class="${this.tab===t?'selected':''}">${esc(t)}</button>`).join('')}</nav>`;}
 player(){const a=this.actor,v=a.getFlag(F,'view')||{recipes:[],projects:[],resources:[],materials:[],budget:0,services:[],orders:[],history:[],requests:[],workshops:[]};let content='';const t=this.tab;
 if(t==='Overview')content=`<div class="art-grid">${cats.map(c=>`<button data-prof="${esc(c)}" class="art-tile"><i class="fas fa-${({'Blacksmithing':'hammer','Alchemy':'flask','Herbalism':'leaf','Mining':'gem','Enchanting':'magic','Cooking':'utensils','Runecrafting':'gem','Engineering':'cogs','Jewelcrafting':'ring'})[c]}"></i><strong>${esc(c)}</strong><small>${['Herbalism','Mining'].includes(c)?v.resources.filter(r=>gatherMatch(c,r)).length+' resources':v.recipes.filter(r=>r.category===c).length+' recipes'}</small></button>`).join('')}</div>`+panel('Active project',v.projects.filter(p=>['active','ready','loss'].includes(p.status)).map(p=>projectHTML(p,v)).join('')||empty);
 else if(t==='Recipes'){const rs=ordered(v.recipes.filter(r=>(this.category==='All'||r.category===this.category)&&r.name.toLowerCase().includes(this.filter.toLowerCase())&&(this.rarityFilter==='All'||rarityLabel(r.rarity)===this.rarityFilter)));const r=rs.find(x=>x.id===this.chosen)||rs[0];const mats=Object.fromEntries(v.materials.map(m=>[m.id,m.qty]));content=`<div class="art-browser"><aside>${['All',...cats.filter(c=>!['Herbalism','Mining'].includes(c))].map(c=>`<button data-category="${esc(c)}" class="${this.category===c?'selected':''}">${esc(c)}</button>`).join('')}</aside><div><input name="filter" placeholder="Search learned recipes" value="${esc(this.filter)}">${rarityPicker(this.rarityFilter)}${rarityGroup(rs,x=>`<button class="art-list ${r?.id===x.id?'selected':''}" data-recipe="${esc(x.id)}"><b>${esc(x.name)}</b><small>${timeLabel(x.minutes)} · ${x.gp} GP</small></button>`)||empty}</div><div>${r?panel(r.name,`<p>${esc(r.effect||r.description)}</p><h4>Materials</h4>${r.materials.map(m=>row(m.name,`<span class="${(mats[m.id]||0)>=m.qty?'ok':'bad'}">${mats[m.id]||0} / ${m.qty}</span>`)).join('')}${row('Tools',esc(r.tools))}${row('Workshop',esc(r.workshop))}${row('Time',timeLabel(r.minutes))}${row('Cost',r.gp+' GP')}${['Enchanting','Runecrafting'].includes(r.category)?select('target',a.items.filter(i=>targetOkay(i,r)).map(i=>[i.id,i.name])):r.category!=='Cooking'&&!r.linked?'<p class="bad">GM must link result item</p>':''}${button('Start Crafting','start',{id:r.id})}`):empty}</div></div>`;}
 else if(t==='Gathering')content=`<div class="art-nav art-gather-filters">${gatherCats.map(c=>`<button type="button" data-category="${esc(c)}" class="${this.category===c?'selected':''}">${esc(c)}</button>`).join('')}${rarityPicker(this.rarityFilter)}</div>`+panel(v.region||'No active region',rarityGroup(v.resources.filter(r=>gatherMatch(this.category,r)&&(this.rarityFilter==='All'||rarityLabel(r.rarity)===this.rarityFilter)),r=>gatherCard(r,v))||empty);
 else if(t==='Cooking')content=panel('Cooking Recipes',rarityGroup(v.recipes.filter(r=>r.category==='Cooking'),r=>`<div class="art-entry">${row(r.name,timeLabel(r.minutes)+' · '+r.quantity+' servings')}<p>${esc(r.effect||'')}</p>${button('View Recipe','viewCooking',{id:r.id})}</div>`)||empty)+mealPanel(a,v);
 else if(t==='Materials')content=panel('Character Inventory',rarityGroup(v.materials,m=>row(m.name,m.qty))||empty)+mealPanel(a,v)+panel('Recipe Scrolls',a.items.filter(i=>i.getFlag(F,'recipeScroll')).map(i=>row(i.name,button('Learn','learn',{id:i.id}))).join('')||empty);
 else if(t==='Learning'){const l=v.learning||{books:[],mentors:[],projects:[],busy:false};content=panel('Learning Projects',l.projects.filter(liveLesson).map(p=>lessonHTML(p,v)).join('')||empty)+panel('Recipe Scrolls',a.items.filter(i=>i.getFlag(F,'recipeScroll')).map(i=>row(i.name,button('Learn Recipe','learn',{id:i.id}))).join('')||empty)+panel('Recipe Books',l.books.map(x=>lessonOfferHTML(x,'book',l.busy)).join('')||empty)+panel('NPC Training',l.mentors.map(x=>lessonOfferHTML(x,'npc',l.busy)).join('')||empty);}
 else if(t==='Projects')content=panel('My Projects',v.projects.filter(p=>['active','paused','ready','loss'].includes(p.status)).map(p=>projectHTML(p,v)).join('')||empty)+panel('Learning Projects',(v.learning?.projects||[]).filter(liveLesson).map(p=>lessonHTML(p,v)).join('')||empty)+panel('Requests',v.requests.map(q=>row(q.name,esc(q.status))).join('')||empty);
 else if(t==='Services')content=v.services.map(n=>panel(n.name,n.recipes.map(r=>row(`${r.name} (${r.gp+n.fee} GP + materials)`,button('Place order','order',{npc:n.id,id:r.id}))).join('')||empty)).join('')+panel('Orders',v.orders.map(o=>row(o.name,esc(o.status)+(o.status==='ready'?button('Collect','collect',{id:o.id}):''))).join('')||empty);
 else if(t==='History')content=panel('Artisan History',v.history.map(h=>`<p>${esc(h.text)}</p>`).join('')||empty);
 return `<header class="art-head"><h2>AVERIS <small>ARTISAN SYSTEM</small></h2>${esc(a.name)} · ${timeLabel(v.budget)} downtime ${button('Refresh','refresh')}</header>${this.nav(['Overview','Recipes','Gathering','Cooking','Materials','Projects','Learning','Services','History'])}${content}`;}
 gm(){if(!state)return '<p>GM database is initializing. Reopen the window.</p>';let c='';const t=this.tab,actors=actorOptions(),a=game.actors.get(this.gmActor)||game.actors.get(actors[0]?.[0]);if(a)this.gmActor=a.id;const as=a?actorState(state,a):null;
 if(t==='Dashboard')c=`<div class="art-grid">${[['Approvals',state.requests.filter(q=>q.status==='pending').length],['Recipes',state.catalog.recipes.length],['Projects',playerProjectStates().flatMap(([,x])=>x.projects).filter(p=>['active','ready','loss'].includes(p.status)).length+playerProjectStates().flatMap(([,x])=>x.learning||[]).filter(p=>p.status==='active').length],['Actors',actors.length],['Regions',Object.keys(state.regions).length],['NPC Orders',state.orders.length]].map(([n,v])=>`<button class="art-tile" data-tab="${n}"><strong>${v}</strong>${n}</button>`).join('')}</div>`;
 else if(t==='Approvals')c=panel('Pending requests',state.requests.filter(q=>q.status==='pending').map(q=>`<div class="art-entry"><b>${esc(q.name)}</b> · ${esc(game.actors.get(q.actor)?.name)} · ${esc(q.kind)}<div>${button(q.kind==='loss'?'Choose losses':'Approve','approve',{id:q.id})}${q.kind!=='loss'?button('Reject','reject',{id:q.id}):''}</div></div>`).join('')||empty);
 else if(t==='Recipes'){const rs=ordered(state.catalog.recipes.filter(r=>(this.category==='All'||r.category===this.category)&&r.name.toLowerCase().includes(this.filter.toLowerCase())&&(this.rarityFilter==='All'||rarityLabel(r.rarity)===this.rarityFilter)));const r=rs.find(x=>x.id===this.chosen)||rs[0];c=`<div class="art-browser"><aside>${['All',...cats.filter(c=>!['Herbalism','Mining'].includes(c))].map(c=>`<button data-category="${esc(c)}" class="${this.category===c?'selected':''}">${esc(c)}</button>`).join('')}${button('New Recipe','newRecipe')}</aside><div><input name="filter" value="${esc(this.filter)}" placeholder="Search recipes">${rarityPicker(this.rarityFilter)}${rarityGroup(rs,x=>`<button data-recipe="${esc(x.id)}" class="art-list ${r?.id===x.id?'selected':''}"><b>${esc(x.name)}</b></button>`)}</div><div>${r?panel(r.name,`<p>${esc(r.effect||r.description)}</p>${row('DC',r.dc)}${row('Time',timeLabel(r.minutes))}${row('Gold',r.gp+' GP')}${r.materials.map(m=>row(m.name,m.qty)).join('')}${row('Result link',esc(state.links.results[r.id]||'Not linked'))}<div class="art-actions">${button('Edit','editRecipe',{id:r.id})}${button('Link Result Item','linkResult',{id:r.id})}${button('Duplicate','duplicateRecipe',{id:r.id})}${button('Create Scroll','createScroll',{id:r.id})}${button('Unlock for actor','unlockSelected',{id:r.id})}</div>`):empty}</div></div>`;}
 else if(t==='Actors'||t==='Workshops'){c=panel('Select Actor',select('actor',actors,this.gmActor));if(as)c+=panel(a.name,`${row('Downtime (minutes)',`<input name="budget" type="number" min="0" value="${as.budget}">`)}${row('Region',select('actorRegion',[['','None'],...Object.entries(state.regions).map(([id,r])=>[id,r.name])],as.region))}<h4>Workshop access</h4>${['Forge','Alchemy Lab','Kitchen','Enchanting Workshop','Runecrafting Workshop','Workbench','Jeweler Bench'].map(w=>`<label><input type="checkbox" name="workshop" value="${w}" ${as.workshops.includes(w)?'checked':''}> ${w}</label>`).join('<br>')}${button('Save actor settings','saveActor')}<h4>Learned recipes (${as.learned.length})</h4>${button('Unlock recipes','unlockBulk')}${as.learned.map(id=>{const r=state.catalog.recipes.find(x=>x.id===id);return r?row(r.name,button('Revoke','revoke',{id})):''}).join('')}`)+panel('NPC Service Configuration',button('Configure NPC','configureNPC'));}
 else if(t==='Learning'){const mentors=game.actors.filter(x=>x.type==='npc').map(x=>[x.id,x.name]);c=panel('Learning Management',button('Create Recipe Book','createBook')+button('Direct GM Unlock','unlockLearning')+'<p>Scrolls are instant; book study uses half of default NPC training time. No learning roll.</p>')+panel('NPC Mentors',select('mentor',mentors)+button('Configure Training','configureTraining')+Object.entries(state.actors).filter(([id,x])=>game.actors.get(id)?.type==='npc'&&x.training?.enabled).map(([id,x])=>row(game.actors.get(id).name,esc(x.training.recipes.length+' offered recipes'))).join(''))+panel('Player Learning Projects',playerProjectStates().map(([actor,x])=>panel(actor.name,(x.learning||[]).filter(liveLesson).map(p=>lessonHTML(p,{budget:x.budget},false)).join('')||empty)).join('')||empty);}
 else if(t==='Regions'){c=panel('World day',`<input name="day" type="number" min="1" value="${state.day}">${button('Set Day','setDay')}${button('New Region','newRegion')}${button('Seed Journal Regions','seedRegions')}`)+Object.entries(state.regions).map(([id,r])=>panel(r.name,button('Add resource patch','addPatch',{id})+rarityGroup(r.patches.map(p=>({...p,name:resource(p.resource).name,rarity:resource(p.resource).rarity})),p=>row(p.name,`${esc(patchStatus(p,state.day))} · ${p.remaining} ${button('Edit','editPatch',{region:id,id:p.id})}`)))).join('')+panel('Gathering Log',(state.gatherLog||[]).slice(0,40).map(x=>`<div class="art-entry"><b>${esc(x.actor)} — ${esc(x.resource)}</b><small> · Day ${x.day} · ${esc(x.region)}</small><p>${esc(x.stage)} · ${esc(x.method)} · Roll ${x.roll} / DC ${x.dc} · ${x.success?'Success':'Failure'} · ${x.quantity} MU</p>${x.hazard?`<p class="bad">Hazard: ${esc(x.hazard)}</p>`:''}</div>`).join('')||empty);}
 else if(t==='Projects')c=playerProjectStates().map(([a,s])=>panel(a.name,(s.projects.filter(p=>['active','paused','ready','loss'].includes(p.status)).map(p=>row(`${p.recipe.name} · ${p.status}`,`${timeLabel(p.progress)} / ${timeLabel(p.recipe.minutes)}`)).join('')+(s.learning||[]).filter(liveLesson).map(p=>lessonHTML(p,{budget:s.budget},false)).join(''))||'<p class="art-muted">No active or paused projects.</p>')).join('')||'<p class="art-muted">No player-owned characters. Assign a character to a player or grant Owner permission.</p>';
 else if(t==='NPC Orders')c=panel('Orders',state.orders.map(o=>`<div class="art-entry">${row(o.recipe.name,esc(o.status))}${esc(game.actors.get(o.npc)?.name)} → ${esc(game.actors.get(o.customer)?.name)}<progress value="${o.progress}" max="${o.recipe.minutes}"></progress>${o.status==='active'?button('Add work','orderWork',{id:o.id}):''}</div>`).join('')||empty);
 else if(t==='Compendiums')c=panel('World Compendiums',`<p>Create and link Artisan items from the catalog. Existing custom links are preserved. SRD base equipment is copied where available; conditional effects marked for review remain manual.</p>${button('Build all Artisan packs','buildAll')}${button('Organize existing packs by rarity','organizePacks')}${button('Create material compendium','buildMaterials')}${button('Create recipe scroll compendium','buildScrolls')}${button('Create crafted item compendiums','buildResults')}`)+panel('Material links',`${select('materialLink',state.catalog.materials.map(m=>[m.id,m.name]))}${button('Link existing material item','linkMaterial')}`);
 else if(t==='Settings')c=panel('Settings',`${row('Approval',select('approval',[['smart','Smart Approval'],['manual','Always Manual'],['auto','Automatic']],state.approval))}${button('Save Settings','saveSettings')}${button('Export catalog','exportCatalog')}${button('Import catalog JSON','importCatalog')}`);
 return `<header class="art-head"><h2>AVERIS <small>GM DASHBOARD</small></h2>Day ${state.day}</header>${this.nav(['Dashboard','Approvals','Recipes','Actors','Regions','Workshops','Projects','Learning','NPC Orders','Compendiums','Settings'])}${c}`;}
 activateListeners(html){const el=html[0]??html;el.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{this.tab=b.dataset.tab;this.filter='';this.category='All';this.rarityFilter='All';this.render({force:false});});el.querySelectorAll('[data-prof]').forEach(b=>b.onclick=()=>{const c=b.dataset.prof;this.tab=['Herbalism','Mining'].includes(c)?'Gathering':c==='Cooking'?'Cooking':'Recipes';this.category=c;this.render({force:false});});el.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{this.category=b.dataset.category;this.render({force:false});});el.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{this.chosen=b.dataset.recipe;this.render({force:false});});const f=el.querySelector('[name=filter]');if(f)f.onchange=()=>{this.filter=f.value;this.render({force:false});};const rf=el.querySelector('[name=rarityFilter]');if(rf)rf.onchange=()=>{this.rarityFilter=rf.value;this.render({force:false});};const ac=el.querySelector('[name=actor]');if(ac)ac.onchange=()=>{this.gmActor=ac.value;this.render({force:false});};el.querySelectorAll('[data-op]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const d=JSON.parse(b.dataset.payload);if(this.actor){if(b.dataset.op==='viewCooking'){this.tab='Recipes';this.category='Cooking';this.rarityFilter='All';this.filter='';this.chosen=d.id;this.render({force:false});return;}if(b.dataset.op==='shareMeal'){const item=this.actor.items.get(d.id),v=this.actor.getFlag(F,'view');if(!item)return;const shares=await distributeDialog(item,v?.cooking?.recipients||[]);if(!shares?.length)return;d.shares=shares;}if(b.dataset.op==='start')d.target=el.querySelector('[name=target]')?.value;if(b.dataset.op==='gather')d.method=b.closest('.art-gather-card')?.querySelector('[name=gatherMethod]')?.value;if(b.dataset.op==='customWork'){const val=await promptField('Work minutes','30');if(val==null)return;d.minutes=Number(val);await request(this.actor,'work',d);}else if(b.dataset.op==='cancelLesson'){if(await foundry.appv1.api.Dialog.confirm({title:'Cancel lesson?',content:'<p>Training gold and spent downtime will not be refunded.</p>'}))await request(this.actor,'cancelLesson',d);}else if(b.dataset.op==='cancel'){if(await foundry.appv1.api.Dialog.confirm({title:'Cancel project?',content:'<p>Materials return; supply gold and work time do not.</p>'}))await request(this.actor,'cancel',d);}else await request(this.actor,b.dataset.op,d);}else await this.gmAction(b.dataset.op,d,el);}catch(e){ui.notifications.error(e.message);console.error(ID,e);}finally{b.disabled=false;}});}
 async gmAction(op,d,el){if(!primary())throw Error('Use the primary active GM');const a=game.actors.get(this.gmActor)||game.actors.get(actorOptions()[0]?.[0]);const value=n=>el.querySelector(`[name=${n}]`)?.value;await serialize(async()=>{switch(op){case 'approve':case 'reject':{const q=state.requests.find(x=>x.id===d.id&&x.status==='pending');if(!q)throw Error('Request no longer pending');if(op==='reject'){q.status='rejected';break;}const ac=actorBy(q.actor),as=actorState(state,ac);if(q.kind==='craft')await begin(ac,as,lookup(q.data.id),q.data.target);else if(q.kind==='gather'){const p=state.regions[as.region]?.patches.find(p=>p.id===q.data.patchId);if(!p)throw Error('Patch not available');const r=resource(p.resource);await gather(ac,as,q.data.patchId,q.data.stage,q.data.method||gatherMethods(r,q.data.stage,p)[0]?.id,true,q.data.region||as.region);}else if(q.kind==='learning')await beginLesson(ac,as,lookup(q.data.id),q.data.kind,q.data.source,q.data.quote);else if(q.kind==='loss'){const p=as.projects.find(x=>x.id===q.data.project&&x.status==='loss');if(!p)throw Error('Project not pending resolution');const n=Math.min(p.outcome.loss,p.recipe.materials.reduce((sum,m)=>sum+m.qty,0));const choice=await promptField(`Choose ${n} lost unit(s), comma-separated IDs`,p.recipe.materials.flatMap(m=>Array(m.qty).fill(m.id)).slice(0,n).join(','),`<p>${p.recipe.materials.map(m=>esc(m.id)+' × '+m.qty).join(', ')}</p><p>Roll: ${p.roll.total} · DC ${p.recipe.dc}</p>`);if(choice==null)return;await complete(ac,as,p,choice.split(',').map(s=>s.trim()).filter(Boolean));}else if(q.kind==='order'){const npc=actorBy(q.data.npc),ns=actorState(state,npc),r=lookup(q.data.id);if(!ns.npc?.enabled||!ns.npc.customers.includes(ac.id)||!ns.learned.includes(r.id))throw Error('Service unavailable');if(state.orders.filter(o=>o.npc===npc.id&&!['collected','failed','rejected'].includes(o.status)).length>=ns.npc.capacity)throw Error('Order queue full');if((await fromUuid(state.links.results[r.id]))?.documentName!=='Item')throw Error('Result Item link missing');checkTools(npc,r);if(!ns.workshops.includes(workshop(r)))throw Error('NPC workshop unavailable');if(['Cooking','Enchanting','Runecrafting'].includes(r.category))throw Error('Only equipment and alchemy NPC orders in preview');if(money(ac)<(r.gp+ns.npc.fee)*100)throw Error('Insufficient funds');const escrow=await take(ac,r.materials);try{await pay(ac,r.gp+ns.npc.fee);}catch(e){await restore(ac,escrow);throw e;}state.orders.push({id:uid(),npc:npc.id,customer:ac.id,recipe:clone(r),status:'active',progress:0,escrow});}q.status='approved';break;}
 case 'saveActor':{const s=actorState(state,a);const b=Number(value('budget'));if(!Number.isInteger(b)||b<0)throw Error('Invalid budget');s.budget=b;s.region=value('actorRegion');s.workshops=[...el.querySelectorAll('[name=workshop]:checked')].map(x=>x.value);break;}
 case 'configureTraining':{const mentor=actorBy(value('mentor'));if(mentor.type!=='npc')throw Error('Select NPC mentor');const ns=actorState(state,mentor),old=ns.training||{customers:[],recipes:[],rates:TRAINING_DEFAULTS};const rs=state.catalog.recipes.filter(r=>ns.learned.includes(r.id));const v=await learningDialog('Configure '+mentor.name,{recipes:rs,selected:old.recipes,customers:playerProjectActors().map(a=>[a.id,a.name]),selectedCustomers:old.customers,rates:{...TRAINING_DEFAULTS,...old.rates}});if(!v)return;for(const q of Object.values(v.rates)){if(!Number.isFinite(q.gp)||q.gp<0||Math.round(q.gp*100)!==q.gp*100||!Number.isInteger(q.minutes)||q.minutes<=0)throw Error('Training price must be nonnegative GP (up to 2 decimals); duration must be positive whole minutes');}ns.training={enabled:true,recipes:v.recipes.filter(id=>ns.learned.includes(id)),customers:v.customers,rates:v.rates};break;}
 case 'createBook':{const id=await choose('Give book to actor',actorOptions());if(!id)return;const v=await learningDialog('Create Recipe Book',{name:'Artisan Recipe Book',recipes:state.catalog.recipes});if(!v)return;if(!v.name?.trim()||!v.recipes.length)throw Error('Choose a name and at least one recipe');await actorBy(id).createEmbeddedDocuments('Item',[bookData(v.name.trim(),v.recipes)]);break;}
 case 'unlockLearning':{const id=await choose('Unlock recipes for player',playerProjectActors().map(a=>[a.id,a.name]));if(!id)return;const ac=actorBy(id),as=actorState(state,ac);const v=await learningDialog('Select recipes to unlock',{name:'GM unlock',recipes:state.catalog.recipes.filter(r=>!as.learned.includes(r.id))});if(v){unlock(ac,v.recipes);note(as,'GM unlocked '+v.recipes.length+' recipes');}break;}
 case 'unlockSelected':{const id=await choose('Unlock for actor',actorOptions());if(id)unlock(actorBy(id),[d.id]);break;}
 case 'unlockBulk':{const ids=await promptField('Recipe IDs (comma-separated; or category name / ALL)','',`<p>Use category name or recipe IDs from exported catalog.</p>`);if(ids!=null){const found=state.catalog.recipes.filter(r=>ids.toUpperCase()==='ALL'||r.category.toLowerCase()===ids.toLowerCase()||ids.split(',').map(x=>x.trim()).includes(r.id));unlock(a,found.map(r=>r.id));}break;}
 case 'revoke':actorState(state,a).learned=actorState(state,a).learned.filter(id=>id!==d.id);break;
 case 'newRecipe':case 'editRecipe':case 'duplicateRecipe':{const original=d.id?lookup(d.id):{name:'New Recipe',category:'Blacksmithing',rarity:'Common',dc:10,minutes:120,gp:5,tools:"Smith's Tools",materials:[],quantity:1,effect:'',description:''};let draft=clone(original);if(op==='duplicateRecipe')draft.name+=' (Copy)';const v=await promptRecipe(draft);if(!v)return;validateRecipe(v);v.id=op==='editRecipe'?d.id:slug(v.category+'-'+v.name);if(op!=='editRecipe'&&state.catalog.recipes.some(r=>r.id===v.id))throw Error('Recipe ID exists');if(op==='editRecipe')state.catalog.recipes=state.catalog.recipes.map(r=>r.id===d.id?v:r);else state.catalog.recipes.push(v);this.chosen=v.id;break;}
 case 'linkResult':{const link=await promptField('Result Item UUID',state.links.results[d.id]||'');if(link==null)return;const item=await fromUuid(link);if(item?.documentName!=='Item')throw Error('Invalid Item UUID');state.links.results[d.id]=link;break;}
 case 'linkMaterial':{const id=value('materialLink');const link=await promptField('Existing material Item UUID',state.links.materialTemplates[id]||'');if(link==null)return;const item=await fromUuid(link);if(item?.documentName!=='Item')throw Error('Invalid Item UUID');state.links.materialTemplates[id]=link;state.links.materials[link]=id;if(item.parent?.documentName==='Actor'||!item.pack)await item.setFlag(F,'material',id);break;}
 case 'createScroll':{const id=await choose('Give scroll to actor',actorOptions());if(id)await actorBy(id).createEmbeddedDocuments('Item',[scrollData(lookup(d.id))]);break;}
 case 'setDay':{const n=Number(value('day'));if(!Number.isInteger(n)||n<1)throw Error('Invalid day');state.day=n;for(const reg of Object.values(state.regions))for(const p of reg.patches)refreshPatch(p,resource(p.resource),state.day);break;}
 case 'seedRegions':{for(const [name,leads] of state.catalog.regions){if(Object.values(state.regions).some(r=>r.name===name))continue;const patches=[];for(const lead of leads.split(',')){const r=state.catalog.resources.find(r=>r.id===slug(lead.replace(/\s*\([^)]*\)/g,'')));if(r)patches.push(newPatch(r,{hidden:r.rarity==='Very Rare'}));}state.regions[uid()]={name,patches};}break;}case 'newRegion':{const name=await promptField('Region name','');if(name?.trim())state.regions[uid()]={name:name.trim(),patches:[]};break;}
 case 'addPatch':{const id=await choose('Resource',ordered(state.catalog.resources).map(r=>[r.id,rarityLabel(r.rarity)+' — '+r.name]));if(id){const r=resource(id);state.regions[d.id].patches.push(newPatch(r,{hidden:r.rarity==='Very Rare'}));}break;}
 case 'editPatch':{const reg=state.regions[d.region],p=reg.patches.find(p=>p.id===d.id);const r=resource(p.resource),v=await patchDialog(r,p);if(v){validatePatch(v,r);const reset=v.resetSearch;delete v.resetSearch;Object.assign(p,v,{id:d.id});if(reset){p.searchBlocked=false;p.failedDay=null;}refreshPatch(p,r,state.day);}break;}
 case 'configureNPC':{if(a.type!=='npc')throw Error('Choose an NPC');const s=actorState(state,a);const n=await promptJSON('NPC service (customer actor IDs)',s.npc||{enabled:true,mode:'roll',fee:10,capacity:3,customers:[]});if(n){if(!['roll','guaranteed'].includes(n.mode)||!Number.isFinite(n.fee)||n.fee<0||!Number.isInteger(n.capacity)||n.capacity<1||!Array.isArray(n.customers))throw Error('Invalid NPC config');s.npc=n;}break;}
 case 'orderWork':{const o=state.orders.find(o=>o.id===d.id&&o.status==='active');if(!o)throw Error('No active order');const n=await promptField('Add NPC work minutes',String(o.recipe.minutes-o.progress));if(n==null)return;const m=Number(n);if(!Number.isInteger(m)||m<=0||m>o.recipe.minutes-o.progress)throw Error('Invalid work minutes');o.progress+=m;if(o.progress===o.recipe.minutes){const ns=actorState(state,actorBy(o.npc)),npc=actorBy(o.npc);const ok=ns.npc.mode==='guaranteed'||(await roll('1d20+'+mod(npc,ability(o.recipe),true))).total>=o.recipe.dc;if(ok){o.status='ready';o.escrow=[];}else{o.status='failed';await restore(actorBy(o.customer),o.escrow);o.escrow=[];}}break;}
 case 'organizePacks':await organizeExisting();break;
 case 'buildAll':await buildMaterials();await buildPack('Artisan Recipe Scrolls','averis-artisan-scrolls',state.catalog.recipes.map(scrollData),'recipeScroll');await buildResults();break;
 case 'buildMaterials':await buildMaterials();break;
 case 'buildScrolls':await buildPack('Artisan Recipe Scrolls','averis-artisan-scrolls',state.catalog.recipes.map(scrollData),'recipeScroll');break;
 case 'buildResults':await buildResults();break;
 case 'saveSettings':state.approval=value('approval');break;
 case 'exportCatalog':saveDataToFile(JSON.stringify(state.catalog,null,2),'application/json','averis-artisan-catalog.json');break;
 case 'importCatalog':{const v=await promptJSON('Import catalog',state.catalog);if(!v)return;if(!Array.isArray(v.recipes)||!Array.isArray(v.materials)||!Array.isArray(v.resources))throw Error('Invalid catalog');v.recipes.forEach(validateRecipe);if(new Set(v.recipes.map(r=>r.id)).size!==v.recipes.length)throw Error('Duplicate recipe ID');state.catalog=v;break;}
 default:throw Error('Unknown GM operation');}await saveAll();});}
}
function unlock(a,ids){const s=actorState(state,a);s.learned=[...new Set([...s.learned,...ids])];}
function validateRecipe(r){if(!r.name||!cats.includes(r.category)||!['Common','Uncommon','Rare','Very Rare'].includes(r.rarity)||!Number.isInteger(r.dc)||r.dc<0||!Number.isInteger(r.minutes)||r.minutes<1||!Number.isFinite(r.gp)||r.gp<0||!Number.isInteger(r.quantity)||r.quantity<1||typeof r.tools!=='string'||!Array.isArray(r.materials)||r.materials.some(m=>!m.id||!m.name||!Number.isInteger(m.qty)||m.qty<1))throw Error('Invalid recipe');}
function scrollData(r){const id='learnRecipe00001';return {name:'Recipe: '+r.name,type:'consumable',img:'icons/svg/book.svg',system:{quantity:1,rarity:r.rarity.toLowerCase().replace(' ',''),type:{value:'scroll'},description:{value:`<p>Learn ${esc(r.name)}. Requires ${esc(r.tools)}.</p><p>Use <b>Learn Recipe</b> to permanently unlock this recipe. The scroll is consumed only after successful learning.</p>`},activities:{[id]:{_id:id,type:'utility',name:'Learn Recipe',activation:{type:'special',value:1},consumption:{targets:[]}}}},flags:{[F]:{recipeScroll:r.id}}};}
const PackClass=()=>foundry.documents.collections.CompendiumCollection;
const ItemClass=()=>CONFIG.Item.documentClass;
const ART_PACKS=['materials','scrolls','equipment','alchemy','meals','runes','enchantments'];
function itemRarity(item){const f=item.flags?.[F]||{},r=state.catalog.recipes.find(r=>r.id===(f.recipe||f.recipeScroll||f.pattern));const mat=state.catalog.materials.find(m=>m.id===f.material);return rarityLabel(f.material?mat?.rarity:r?.rarity??item.system?.rarity);}
async function organizePack(p,docs=null){
 const all=docs||await p.getDocuments(),managed=all.filter(i=>{const f=i.flags?.[F]||{};return f.recipe||f.recipeScroll||f.pattern||f.material;});
 if(!managed.length)return 0;
 const folders=new Map(),found=Array.from(p.folders||[]);for(const r of RARITIES){if(!managed.some(i=>itemRarity(i)===r))continue;const name=String(rarityRank(r)+1).padStart(2,'0')+' — '+r;let f=found.find(x=>x.name===name&&!x.folder);if(!f)f=await CONFIG.Folder.documentClass.create({name,type:'Item',sorting:'a',sort:(rarityRank(r)+1)*100000},{pack:p.collection});folders.set(r,f.id);}
 const updates=[];for(const i of managed){const r=itemRarity(i),folder=folders.get(r);if(!folder)continue;const old=i.folder?.id??i._source?.folder??null;const data={_id:i.id};if(old!==folder)data.folder=folder;
 // Unclassified raw ingredients have no rarity assigned by their source. Do not invent one.
 if(r!=='Unclassified'&&i.system&&Object.hasOwn(i.system,'rarity')&&rarityLabel(i.system.rarity)!==r)data['system.rarity']=r.toLowerCase().replace(/\s/g,'');
 if(Object.keys(data).length>1)updates.push(data);}
 for(let k=0;k<updates.length;k+=25)await ItemClass().updateDocuments(updates.slice(k,k+25),{pack:p.collection});return updates.length;
}
async function organizeExisting(){let n=0;for(const suffix of ART_PACKS){const p=game.packs.get('world.averis-artisan-'+suffix);if(!p)continue;const locked=p.locked;try{if(locked)await p.configure({locked:false});n+=await organizePack(p);}finally{if(locked)await p.configure({locked:true});}}ui.notifications.info('Artisan: '+n+' entries reorganized by rarity.');}
async function buildPack(label,name,docs,key){
 let p=game.packs.get('world.'+name);
 if(!p)p=await PackClass().createCompendium({type:'Item',label,name,package:'world',ownership:{PLAYER:'NONE',ASSISTANT:'OWNER'}});
 const locked=p.locked;if(locked)await p.configure({locked:false});
 try{
  const existing=await p.getDocuments(),byKey=new Map(existing.filter(i=>i.getFlag(F,key)).map(i=>[i.getFlag(F,key),i])),byName=new Map(existing.map(i=>[i.name,i]));
  const fresh=docs.filter(d=>!byKey.has(d.flags[F][key])&&!byName.has(d.name));let created=0;
  for(let i=0;i<fresh.length;i+=25){const result=await ItemClass().createDocuments(fresh.slice(i,i+25),{pack:p.collection});for(const item of result){byKey.set(item.getFlag(F,key),item);created++;}}
  for(const d of docs){const k=d.flags[F][key],old=byName.get(d.name);if(!byKey.has(k)&&old?.getFlag(F,key)===k)byKey.set(k,old);}
  // Old scrolls are kept as loot; the sheet and inventory Learn button supports both.
  await organizePack(p,Array.from(byKey.values()));ui.notifications.info(`${label}: ${created} new entries. ${byKey.size} linked templates.`);
  return byKey;
 }finally{await p.configure({locked:true});}
}
async function buildMaterials(){const docs=state.catalog.materials.map(m=>matData(m.id,1)),index=await buildPack('Artisan Materials','averis-artisan-materials',docs,'material');for(const [id,item] of index){if(!state.links.materialTemplates[id])state.links.materialTemplates[id]=item.uuid;state.links.materials[item.uuid]=id;}await persist();}
const BASES=[
 ['crossbow bolts','Crossbow Bolts'],['sling bullets','Sling Bullets'],['arrows','Arrows'],['war pick','War Pick'],['warhammer','Warhammer'],['battleaxe','Battleaxe'],['greatsword','Greatsword'],['greataxe','Greataxe'],['shortsword','Shortsword'],['longsword','Longsword'],['longbow','Longbow'],['rapier','Rapier'],['dagger','Dagger'],['javelin','Javelin'],['glaive','Glaive'],['spear','Spear'],['maul','Maul'],['darts','Dart'],['breastplate','Breastplate'],['chain shirt','Chain Shirt'],['scale mail','Scale Mail'],['chain mail','Chain Mail'],['half plate','Half Plate'],['splint','Splint'],['plate armor','Plate Armor'],['shield','Shield'],['grappling hook','Grappling Hook'],['crowbar','Crowbar']
];
const explicitBases={'Black Iron Blade':'Longsword','Stormforged Blade':'Longsword','Eclipse Edge':'Longsword','Stormspark Bolts (2)':'Crossbow Bolts','Abyssal Bolts (2)':'Crossbow Bolts','Black Iron Siege Bolts (2)':'Crossbow Bolts','Abyssal Bulwark':'Shield','Black Iron Greatguard':'Shield','Black Iron Guard':'Shield','Black Iron Plate Inserts':null,'Black Iron Spaulders':null,'Copper Lock Mechanism':'Lock','Copper Manacles':'Manacles','Copper Signal Bell':'Bell','Acid Vial':'Acid','Antitoxin':'Antitoxin',"Alchemist's Fire":"Alchemist's Fire",'Potion of Healing':'Potion of Healing','Herbal Healing Draught':'Potion of Healing','Potion of Greater Healing':'Potion of Greater Healing','Potion of Superior Healing':'Potion of Superior Healing','Potion of Supreme Healing':'Potion of Supreme Healing'};
function baseName(r){if(Object.hasOwn(explicitBases,r.name))return explicitBases[r.name];if(r.category!=='Blacksmithing')return null;const n=r.name.toLowerCase();return BASES.find(([key])=>n.includes(key))?.[1]||null;}
async function srdIndex(){const out=new Map();for(const id of ['dnd5e.items','dnd5e.equipment24']){const p=game.packs.get(id);if(!p)continue;const idx=await p.getIndex();for(const x of idx){const key=String(x.name).toLowerCase().replace(/[’‘]/g,"'");if(!out.has(key))out.set(key,{p,id:x._id});}}return out;}
async function resultData(r,index){
 const base=baseName(r),hit=base?index.get(base.toLowerCase()):null;let data,manual=true;
 if(hit){const original=await hit.p.getDocument(hit.id);data=original.toObject();delete data._id;delete data.folder;delete data._stats;delete data.ownership;data.flags={};manual=!/Type: Standard D&D equipment/i.test(r.description)||/silvered/i.test(r.name);}
 else{const potion=r.category==='Alchemy',meal=r.category==='Cooking';data={type:potion||meal?'consumable':'loot',img:potion?'icons/svg/potion.svg':'icons/svg/item-bag.svg',system:{quantity:1,description:{value:''},...(potion||meal?{type:{value:potion?'potion':'food'}}:{})}};}
 data.name=r.name;data.system.quantity=1;data.system.rarity=['Common','Uncommon','Rare','Very Rare'].includes(r.rarity)?r.rarity.toLowerCase().replace(' ',''):'common';
 // An ordinary item keeps its native SRD activities, damage, and AC. Homebrew additions remain text until reviewed.
 if(r.attunement&&['weapon','equipment'].includes(data.type))data.system.attunement='required';
 data.system.description={...(data.system.description||{}),value:`<p>${esc(r.effect||r.description)}</p>${manual?'<p><em>Artisan: custom or missing base mechanics require GM review. Apply special effects manually.</em></p>':''}`};
 data.flags={[F]:{recipe:r.id,template:true,manualReview:manual,sourceBase:base||null}};
 if(r.category==='Cooking')return {...mealData(r,1,true),flags:{[F]:{meal:r.effect,mealRecipe:r.id,recipe:r.id,template:true,manualReview:false}}};
 return data;
}
async function buildResults(){
 const index=await srdIndex();
 const groups=[['Artisan Equipment','averis-artisan-equipment',['Blacksmithing','Engineering','Jewelcrafting']],['Artisan Alchemy','averis-artisan-alchemy',['Alchemy']],['Artisan Meals','averis-artisan-meals',['Cooking']]];
 for(const [label,name,categories] of groups){const docs=[];for(const r of state.catalog.recipes.filter(r=>categories.includes(r.category)))docs.push(await resultData(r,index));const items=await buildPack(label,name,docs,'recipe');for(const [id,i] of items)if(!state.links.results[id])state.links.results[id]=i.uuid;await persist();}
 // Runes and enchants are applied to existing equipment; these packs are GM reference pattern items, not physical outputs.
 for(const [cat,name] of [['Runecrafting','runes'],['Enchanting','enchantments']])await buildPack('Artisan '+cat,'averis-artisan-'+name,state.catalog.recipes.filter(r=>r.category===cat).map(r=>({name:r.name,type:'loot',img:'icons/svg/book.svg',system:{quantity:1,rarity:r.rarity.toLowerCase().replace(' ',''),description:{value:esc(r.effect||r.description)}},flags:{[F]:{pattern:r.id}}})),'pattern');
}
function promptRecipe(draft){return new Promise((resolve,reject)=>{const fields=[['name','Name',draft.name],['dc','DC (GM only)',draft.dc],['minutes','Time in minutes',draft.minutes],['gp','Supply cost (GP)',draft.gp],['quantity','Output quantity',draft.quantity],['tools','Required tools',draft.tools],['target','Target type (rune/enchantment)',draft.target||'']];new foundry.appv1.api.Dialog({title:'Recipe Editor',content:`<div style="max-height:530px;overflow:auto">${fields.map(([k,l,v])=>`<div class="form-group"><label>${esc(l)}</label><input name="${k}" value="${esc(v)}"></div>`).join('')}<div class="form-group"><label>Profession</label>${select('category',cats.map(c=>[c,c]),draft.category)}</div><div class="form-group"><label>Rarity</label>${select('rarity',['Common','Uncommon','Rare','Very Rare'].map(c=>[c,c]),draft.rarity)}</div><div class="form-group"><label>Ability</label>${select('ability',[['','Default'],['str','Strength'],['dex','Dexterity'],['int','Intelligence'],['wis','Wisdom']],draft.ability||'')}</div><label>Materials: one line per material ID, quantity</label><textarea name="materials" style="height:95px">${esc(draft.materials.map(m=>`${m.id}, ${m.qty}`).join('\n'))}</textarea><label>Effect</label><textarea name="effect">${esc(draft.effect||'')}</textarea><label>Description</label><textarea name="description">${esc(draft.description||'')}</textarea><label><input name="attune" type="checkbox" ${draft.attunement?'checked':''}> Attunement</label></div>`,buttons:{ok:{label:'Save',callback:h=>{try{const get=k=>h.find(`[name=${k}]`).val(),out={...draft};for(const [k] of fields)out[k]=['dc','minutes','gp','quantity'].includes(k)?Number(get(k)):get(k);for(const k of ['category','rarity','ability','effect','description'])out[k]=get(k);out.attunement=h.find('[name=attune]').prop('checked');out.materials=get('materials').split(/\n/).filter(x=>x.trim()).map(x=>{const [id,q]=x.split(',').map(z=>z.trim());const m=state.catalog.materials.find(m=>m.id===id);if(!m)throw Error('Unknown material ID: '+id);return {id,name:m.name,qty:Number(q)};});resolve(out);}catch(e){reject(e);}}},cancel:{label:'Cancel',callback:()=>resolve(null)}},close:()=>resolve(null)},{width:640}).render(true);});}
function promptField(title,initial='',extra=''){return new Promise(resolve=>new foundry.appv1.api.Dialog({title,content:`${extra}<input type="text" name="v" value="${esc(initial)}">`,buttons:{ok:{label:'Confirm',callback:h=>resolve(h.find('[name=v]').val())},cancel:{label:'Cancel',callback:()=>resolve(null)}},default:'ok',close:()=>resolve(null)}).render(true));}
function promptJSON(title,obj){return new Promise((resolve,reject)=>new foundry.appv1.api.Dialog({title,content:`<p>Edit structured data. IDs must be stable.</p><textarea name="v" style="height:420px;width:100%">${esc(JSON.stringify(obj,null,2))}</textarea>`,buttons:{ok:{label:'Save',callback:h=>{try{resolve(JSON.parse(h.find('[name=v]').val()));}catch(e){reject(e);}}},cancel:{label:'Cancel',callback:()=>resolve(null)}},close:()=>resolve(null)},{width:720}).render(true));}
function choose(title,options){return new Promise(resolve=>new foundry.appv1.api.Dialog({title,content:select('v',options),buttons:{ok:{label:'Select',callback:h=>resolve(h.find('[name=v]').val())},cancel:{label:'Cancel',callback:()=>resolve(null)}},close:()=>resolve(null)}).render(true));}
function openSingle(a=null){const key=a?'actor:'+a.uuid:'gm';let w=windowByKey.get(key);if(w){if(w.rendered){w.bringToFront?.();w.maximize?.();}return w;}w=new ArtisanWindow(a);w.windowKey=key;windowByKey.set(key,w);Promise.resolve(w.render({force:true})).catch(e=>{if(windowByKey.get(key)===w)windowByKey.delete(key);wins.delete(w);console.error(ID,e);ui.notifications.error(e.message);});return w;}
function openActor(a){if(!a||!a.isOwner){ui.notifications.warn('Select an owned character or NPC');return;}return openSingle(a);}
function openGM(){if(!game.user.isGM)return;if(!primary()){ui.notifications.warn('Use the primary active GM');return;}return openSingle();}
function learnScroll(item){const a=item?.parent;if(a?.documentName!=='Actor'||!a.isOwner||!item.getFlag(F,'recipeScroll'))return;request(a,'learn',{id:item.id}).catch(e=>ui.notifications.error(e.message));}
Hooks.on('dnd5e.preUseActivity',activity=>{const item=activity.item;if(item?.getFlag(F,'mealRecipe')){const a=item.parent;if(a?.isOwner&&a.documentName==='Actor')request(a,'eat',{id:item.id}).catch(e=>ui.notifications.error(e.message));return false;}if(!item?.getFlag(F,'recipeScroll'))return;learnScroll(item);return false;});
function addLearnControl(app,html){const root=html?.[0]??html??app.element?.[0]??app.element;if(!root?.querySelectorAll)return;const doc=app.document??app.actor??app.item;if(doc?.documentName==='Item'&&doc.getFlag(F,'recipeScroll')&&doc.parent?.isOwner&&doc.parent.documentName==='Actor'){if(root.querySelector('.art-learn-scroll'))return;const target=root.querySelector('.window-content')??root;const b=document.createElement('button');b.type='button';b.className='art-learn-scroll';b.innerHTML='<i class="fas fa-book-open"></i> Learn Recipe';b.onclick=()=>learnScroll(doc);target.prepend(b);return;}
 if(doc?.documentName!=='Actor'||!doc.isOwner)return;
 for(const item of doc.items.filter(i=>i.getFlag(F,'recipeScroll'))){const row=root.querySelector('[data-item-id="'+item.id+'"]')??root.querySelector('[data-document-id="'+item.id+'"]');if(!row||row.querySelector('.art-learn-scroll'))continue;const target=row.querySelector('.item-controls')??row.querySelector('.item-name')??row;const b=document.createElement('a');b.className='art-learn-scroll';b.setAttribute('role','button');b.title='Learn Recipe';b.innerHTML='<i class="fas fa-book-open"></i> Learn';b.onclick=e=>{e.preventDefault();e.stopPropagation();learnScroll(item);};target.append(b);}
}
Hooks.on('renderApplicationV2',addLearnControl);Hooks.on('renderActorSheet',addLearnControl);Hooks.on('renderItemSheet',addLearnControl);
Hooks.once('ready',async()=>{game.modules.get(ID).api={openActor,openGM,learnScroll};try{await init();}catch(e){console.error(ID,e);ui.notifications.error('Artisan database initialization failed: '+e.message);} });
Hooks.on('updateActor',(a,changes,options,userId)=>{if(changes.flags?.[F]?.view)refresh();if(!primary()||!state)return;const r=changes.flags?.[F]?.request;if(!r?.nonce)return;const u=game.users.get(userId);if(!u||!a.testUserPermission(u,'OWNER'))return;serialize(async()=>{const as=actorState(state,a);as.processed??=[];if(as.processed.includes(r.nonce))return;as.processed.push(r.nonce);as.processed=as.processed.slice(-100);try{await action(a,r.op,r.data||{});}catch(e){note(as,'Request rejected: '+e.message);await ChatMessage.create({content:`Artisan: ${esc(e.message)}`,whisper:[u.id]});}await saveAll();});});
Hooks.on('updateUser',()=>{if(primary()&&!state)serialize(init).catch(console.error);});
Hooks.on('createActor',a=>{if(primary()&&state)serialize(async()=>{actorState(state,a);await saveAll();});});
Hooks.on('getHeaderControlsApplicationV2',(app,controls)=>{const a=app.document??app.actor;if(a?.documentName==='Actor'&&a.isOwner&&['npc','character'].includes(a.type)&&!controls.some(c=>c.action==='averisArtisan'))controls.push({icon:'fa-solid fa-hammer',label:'Artisan',action:'averisArtisan',onClick:()=>openActor(a)});});
Hooks.on('getActorSheetHeaderButtons',(app,buttons)=>{if(app instanceof foundry.applications.api.ApplicationV2)return;if(app.actor?.isOwner&&!buttons.some(b=>b.class==='averis-artisan-button'))buttons.unshift({label:'Artisan',class:'averis-artisan-button',icon:'fas fa-hammer',onclick:()=>openActor(app.actor)});});
Hooks.on('renderActorSheet',(app,html)=>{if(app instanceof foundry.applications.api.ApplicationV2)return;const a=app.actor||app.document,root=html[0]||html;if(!a?.isOwner||!root?.querySelector||root.querySelector('.averis-artisan-button'))return;const header=root.querySelector('.window-header')||app.element?.[0]?.querySelector('.window-header');if(!header||header.querySelector('.averis-artisan-button'))return;const b=document.createElement('a');b.className='averis-artisan-button';b.innerHTML='<i class="fas fa-hammer"></i> Artisan';b.onclick=()=>openActor(a);header.append(b);});
Hooks.on('getSceneControlButtons',controls=>{if(!game.user.isGM)return;const tool={name:'averis-artisan',title:'Artisan GM',icon:'fa-solid fa-hammer',button:true,onChange:()=>openGM()};if(Array.isArray(controls)){const token=controls.find(c=>c.name==='token');token?.tools?.push(tool);}else {const token=controls.tokens??controls.token??Object.values(controls).find(c=>['token','tokens'].includes(c.name));if(token?.tools)token.tools[tool.name]=tool;}});

for(const event of ['createItem','updateItem','deleteItem'])Hooks.on(event,(i,...args)=>{const a=i.parent;if(!primary()||!state||a?.documentName!=='Actor')return;const userId=args.at(-1);serialize(async()=>{await publish(a);refresh();}).catch(console.error);});

Hooks.on('dnd5e.restCompleted',(a,result,config)=>{if(!a?.isOwner)return;const longRest=Boolean(result?.longRest??config?.longRest??config?.type==='long');const spent=Math.abs(Number(result?.dhd??0));if(primary()&&state){serialize(async()=>{await applyMealRest(a,actorState(state,a),longRest,spent);await saveAll();}).catch(console.error);}else if(!game.user.isGM)request(a,'mealRest',{longRest,spent}).catch(console.error);});
Hooks.on('updateWorldTime',()=>{if(primary()&&state&&Object.values(state.actors).some(as=>as.meal&&!isMealActive(as.meal,mealNow(),state.day)))serialize(saveAll).catch(console.error);});
Hooks.on('updateActor',(a,changes,options)=>{if(!primary()||!state||options?.artisanMeal)return;const value=foundry.utils.getProperty(changes,'system.attributes.hp.temp')??changes['system.attributes.hp.temp'];if(value===undefined)return;const meal=state.actors[a.id]?.meal;if(!meal?.ownsTemp)return;trackMealTemp(meal,Number(value));serialize(saveAll).catch(console.error);});
